<?php
 namespace QQWorld\GiftMessage\Observer; use QQWorld\Framework\Event\ObserverInterface; class SalesEventOrderToQuoteObserver implements ObserverInterface { protected $_giftMessageMessage = null; protected $_messageFactory; public function __construct( \QQWorld\GiftMessage\Model\MessageFactory $messageFactory, \QQWorld\GiftMessage\Helper\Message $giftMessageMessage ) { $this->_messageFactory = $messageFactory; $this->_giftMessageMessage = $giftMessageMessage; } public function execute(\QQWorld\Framework\Event\Observer $observer) { $order = $observer->getEvent()->getOrder(); if ($order->getReordered()) { return $this; } if (!$this->_giftMessageMessage->isMessagesAllowed('order', $order, $order->getStore())) { return $this; } $giftMessageId = $order->getGiftMessageId(); if ($giftMessageId) { $giftMessage = $this->_messageFactory->create()->load($giftMessageId)->setId(null)->save(); $observer->getEvent()->getQuote()->setGiftMessageId($giftMessage->getId()); } return $this; } } 